import xarray as xr
import numpy as np
import pytest

def test_rolling_mean_ddof():
    da = xr.DataArray(np.arange(10), dims="x")
    rolling = da.rolling(x=3)
    try:
        rolling.mean(ddof=1)
    except TypeError as e:
        print(f"Caught expected TypeError: {e}")
        return
    except Exception as e:
        pytest.fail(f"Caught unexpected exception: {type(e).__name__}: {e}")

    pytest.fail("rolling.mean() should have raised TypeError when passed ddof")

if __name__ == "__main__":
    test_rolling_mean_ddof()

